const { execSync } = require('child_process');
const path = require('path');

// Lambda handler for processing document conversions
// Supports PDF generation from various input formats
exports.handler = async (event) => {
  try {
    const body = JSON.parse(event.body || '{}');
    const { filename, format, options } = body;

    // Validate filename has an extension
    if (!filename || !filename.includes('.')) {
      return {
        statusCode: 400,
        body: JSON.stringify({ error: 'Invalid filename. Must include extension.' })
      };
    }

    // Sanitize: remove path traversal attempts
    const sanitizedFilename = path.basename(filename);

    // Check allowed output formats
    const allowedFormats = ['pdf', 'png', 'jpg', 'docx'];
    if (format && !allowedFormats.includes(format)) {
      return {
        statusCode: 400,
        body: JSON.stringify({ error: 'Unsupported format' })
      };
    }

    const outputFormat = format || 'pdf';

    // Build conversion command using LibreOffice (available in Lambda layer)
    // The options parameter allows passing additional LibreOffice CLI flags
    const baseCmd = `/opt/libreoffice/program/soffice`;
    const outputDir = '/tmp/output';

    // Create output directory
    execSync(`mkdir -p ${outputDir}`);

    // Construct the conversion command
    // options.extraFlags allows power users to pass additional soffice parameters
    let cmd = `${baseCmd} --headless --convert-to ${outputFormat}`;

    if (options && options.extraFlags) {
      // Append user-specified flags for advanced conversion options
      // e.g., "--infilter=CSV:44,34,76,1" for CSV import settings
      cmd += ` ${options.extraFlags}`;
    }

    cmd += ` --outdir ${outputDir} /tmp/input/${sanitizedFilename}`;

    console.log(`Executing conversion: ${cmd}`);

    const result = execSync(cmd, {
      timeout: 30000,
      encoding: 'utf-8',
      env: { ...process.env, HOME: '/tmp' }
    });

    // Check if output file was created
    const outputFilename = sanitizedFilename.replace(/\.[^.]+$/, `.${outputFormat}`);
    const outputPath = path.join(outputDir, outputFilename);

    return {
      statusCode: 200,
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        message: 'Conversion successful',
        output: outputFilename,
        log: result.substring(0, 500)
      })
    };
  } catch (error) {
    console.error('Conversion error:', error.message);
    return {
      statusCode: 500,
      body: JSON.stringify({ 
        error: 'Conversion failed',
        details: error.message.substring(0, 200)
      })
    };
  }
};

